import{_ as s,o as n,c as e,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"HunyuanWorld 1.0: Generating Immersive, Explorable, and Interactive 3D Worlds from Words or Pixels","description":"","frontmatter":{"title":"HunyuanWorld 1.0: Generating Immersive, Explorable, and Interactive 3D Worlds from Words or Pixels","arxiv":"2507.21809","date":"2025-07-29","authors":"HunyuanWorld Team, Zhenwei Wang, Yuhao Liu, Junta Wu, Zixiao Gu, Haoyuan Wang, Xuhui Zuo, Tianyu Huang, Wenhuan Li, et al.（末两位 Tengfei Wang、Chunchao Guo）","categories":"cs.CV","topics":"世界模型, 3D 场景生成, 全景图代理","outline":[2,2]},"headers":[],"relativePath":"papers/2507.21809.md","filePath":"papers/2507.21809.md","lastUpdated":null}'),r={name:"papers/2507.21809.md"};function o(i,a,l,p,u,c){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="hunyuanworld-1-0-generating-immersive-explorable-and-interactive-3d-worlds-from-words-or-pixels" tabindex="-1">HunyuanWorld 1.0: Generating Immersive, Explorable, and Interactive 3D Worlds from Words or Pixels <a class="header-anchor" href="#hunyuanworld-1-0-generating-immersive-explorable-and-interactive-3d-worlds-from-words-or-pixels" aria-label="Permalink to &quot;HunyuanWorld 1.0: Generating Immersive, Explorable, and Interactive 3D Worlds from Words or Pixels&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2507.21809" target="_blank" rel="noreferrer">2507.21809</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-07-29</td></tr><tr><td><strong>作者</strong></td><td>HunyuanWorld Team, Zhenwei Wang, Yuhao Liu, Junta Wu, Zixiao Gu, Haoyuan Wang, Xuhui Zuo, Tianyu Huang, Wenhuan Li, et al.（腾讯混元；arXiv 署名共 55 条，首条为团队名，末两位 Tengfei Wang、Chunchao Guo）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用全景图当 360° 世界代理，让 VLM 把它拆成天空/背景/物体多层，逐层估深度并对齐后 sheet warping 成网格，直接产出可导入游戏引擎、物体可单独拖动的 3D 世界。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文要的不是&quot;生成一段看起来像 3D 的视频&quot;，而是生成一个<strong>能导出成 mesh、能塞进 Unity/UE、里面的车能被单独拖走</strong>的 3D 世界，输入只有一句话或一张图。这三个要求都不是学术指标，而是工程交付条件：VR 头显需要 360° 无缝覆盖，物理引擎需要三角面片做碰撞检测，游戏开发需要物体是分离的实例而不是一整块烘死的几何。</p><p>重要性在于这些条件同时成立时，&quot;世界生成&quot;才第一次从演示视频变成可用资产。作者列的应用面（VR、物理仿真、游戏开发、物体交互）都建立在&quot;输出是标准 mesh&quot;这一点上——而这恰恰是过去两年视觉效果最好的那批方法做不到的。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文把前人分成两条线，并且给了相当具体的批评。</p><p>视频路线（HunyuanVideo、CogVideoX、Wan2.1 作基座，CameraCtrl II 与 Cosmos 用 Plücker 坐标编码相机位姿，Streetscapes 用多帧 layout 条件做自回归长程扩展，Voyager 与 Wu et al. 用显式 3D 点云增强空间一致性）已经能做到视觉多样性高、能按轨迹控制。作者指出三个硬伤：底层是 2D 帧表示，没有真 3D 一致性，长视频里误差累积导致内容漂移；每帧都要顺序生成，渲染成本高到不能实时；帧序列这种格式根本进不了图形管线。</p><p>3D 路线里，程序化方法（Infinigen 系列、SceneX、LayoutGPT）几何可靠但依赖规则；学习型方法（LucidDreamer、WonderJourney、WonderWorld、CAT3D、DimensionX、Director3D、Scene4U、LayerPano3D）先用扩散模型补出多视角图，再逐场景优化 3DGS。作者的批评落在数据与表示上：3D 场景数据比图像/视频少几个数量级；现有 3D 表示对大场景要么无结构要么显存不友好；生成结果是整块的，物体没被分离。</p><p>值得强调的是，&quot;分层&quot;这个想法并非本文首创——LayerPano3D 已经用 depth clustering 把全景分层。作者的区分点很窄但很实：LayerPano3D 落到 3DGS，而 3DGS 不能直接交给美术和引擎；本文落到分层 <strong>mesh</strong>。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>把本文的贡献暂时忘掉，2025 年中能拿到的线索是这些：第一，等距柱状投影（ERP）全景图是唯一一种能用<strong>单张 2D 图</strong>覆盖完整 360°×180° 的格式，而 2D 扩散模型的数据规模和质量远超任何 3D 数据集；第二，美术做场景的标准做法本来就是天空盒 + 地形网格 + 若干独立资产三层；第三，MoGe、UniK3D 这类开放域单目几何估计已经足够好；第四，WorldSheet 早就证明了&quot;图 + 深度 → 网格 sheet&quot;是可行的。</p><p>顺着走：既然 3D 数据不够而 2D 数据够，就别直接生成 3D，先生成一张全景当世界代理，把生成的难题压回 2D；既然美术是分层建模的，就让模型也分层，这样物体天然分离，交互就白送了；既然分层后每层都是&quot;带 mask 的全景 + 深度&quot;，那 sheet warping 就能把每层直接变成网格，还顺带保住了遮挡顺序。剩下的问题只有两个：全景的左右接缝和极区畸变，以及层与层之间深度尺度不一致。这两个问题恰好对应论文里的 circular denoising 与跨层深度对齐。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>全景图是 2D 生成模型与 3D 世界之间最便宜的中介：它让你用图像模型的数据规模去覆盖 360° 视野。但全景只能转头不能走动，因为遮挡区域没有信息——所以真正的关键动作是<strong>先按语义把这张全景拆成天空、背景、若干物体层，逐层把被挡住的部分 inpaint 回来</strong>，于是每一层都成了完整的、可以独立 warp 成网格的表面。分层不是为了好看，是为了把&quot;看不见的地方&quot;补出来，同时让物体天然可分离。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>用一个真实的输入走一遍：用户输入中文提示&quot;雨夜的赛博朋克街道&quot;。</p><ol><li><strong>提示改写</strong>。用户的自然语言与训练 caption 的分布差别很大，先用 LLM 把中文翻译并扩写成细节丰富的描述。若输入是图片，则先用 MoGe/UniK3D 估内参把透视图反投影到 ERP 空间，再由 VLM 生成 scene-aware prompt——关键细节是：VLM 先识别输入图里的显著物体（比如一尊雕像），把它们放进 <strong>negative prompt</strong>，避免生成的全景里到处复制这尊雕像。</li><li><strong>全景生成</strong>。Panorama-DiT（DiT 架构）出 ERP 全景。两个专门针对全景的技巧：训练时以概率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span>、位移比例 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> 随机上下平移 GT 全景做 elevation-aware augmentation；推理时用 circular padding 加渐进 blending 的 circular denoising，保住左右边界的语义与结构连续。</li><li><strong>Agentic 世界分层</strong>。VLM 识别需要单独建模的实例（车、招牌、路灯），并按语义与空间关系再分子层（近处车辆与远处楼体分开）。全景检测的坑是物体会被 ERP 边界切成两半，所以先 circular padding 再送 Grounding DINO，检测框坐标再映射回原图，接着用 ZIM 出像素级 mask，最后按面积做 NMS 把跨边界的碎片合并。随后自回归地&quot;抠掉物体 → 补全该层&quot;，背景补全模型是在自建的全景物体移除三元组数据集（mask、含物体全景、去物体全景）上微调的 Panorama-DiT，天空层另用 sky HDRI 数据微调。</li><li><strong>逐层重建</strong>。先对原始全景估一张基础深度图，第一前景层的深度直接从中取；后续层各自估深度后，用重叠区域距离最小化与基础深度对齐；天空层给一个略大于全场景最大深度的常数。然后按 WorldSheet 的 sheet warping 把每层变成网格，并对极区做平滑、对 mask 边界做抗锯齿。前景有两种策略：直接投影，或抠出实例交给 Hunyuan3D 生成完整 3D 资产再用自动摆放算法放回场景。背景先做自适应深度压缩再 warp。也支持分层 3DGS 作为替代表示。</li><li><strong>长程扩展</strong>。要走出全景覆盖范围时，接 Voyager：用已生成的 3D 场景初始化点云缓存，把缓存投影到目标视角作为部分引导，生成空间一致的 RGB-D 视频，再把新帧写回缓存并做点云剔除，形成闭环。</li><li><strong>交付优化</strong>。离线用 decimation + 纹理烘焙 + XAtlas UV 参数化压掉约 80% 体积；Web 端用 Draco 压掉约 90%。推理端用 TensorRT，对非关键去噪步走缓存推理，CFG 的正负分支放到不同 GPU 上并行。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。唯一涉及数学的两处（ERP 球面参数化、跨层深度的重叠区域对齐）在技术报告里只有文字描述，没有给出公式。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>因为没有 ground truth，评测只能走&quot;输入-输出对齐 + 无参考视觉质量&quot;这条路：CLIP-I / CLIP-T 测语义对齐，BRISQUE、NIQE、Q-Align 测视觉质量；所有对比都在从全景或 3D 场景渲染出的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">960</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">960</span></span></span></span>、90° FOV 透视图上算。</p><p><strong>问题一：全景本身够好吗？</strong> 图生全景对比 Diffusion360 与 MVDiffusion，本文在四项指标上全胜（BRISQUE 45.2 / NIQE 5.8 / Q-Align 4.3 / CLIP-I 85.1，对比 Diffusion360 的 71.4 / 7.8 / 1.9 / 73.9）。文生全景再加 PanFusion 与 LayerPano3D 两个基线，本文 40.8 / 5.8 / 4.4 / CLIP-T 24.3，同样全项领先（次优 LayerPano3D 为 49.6 / 6.5 / 3.7 / 21.5）。</p><p><strong>问题二：立起来的 3D 世界够好吗？</strong> 图生世界对比 WonderJourney 与 DimensionX，在方位角 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0°</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">15°</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">90°</span><span class="mclose">}</span></span></span></span> 渲七个视角，本文 36.2 / 4.6 / 3.9 / 84.5 优于 DimensionX 的 45.2 / 6.3 / 3.5 / 83.3。文生世界对比 LayerPano3D 与 Director3D，在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0°</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">60°</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">300°</span><span class="mclose">}</span></span></span></span> 渲六个视角，本文 34.6 / 4.3 / 4.2 / 24.0，而 LayerPano3D 为 35.3 / 4.8 / 3.9 / 22.0——这一组差距明显收窄，与&quot;两者都用分层全景&quot;的事实吻合。作者另外提到 Director3D 在很多样例上生成不了长程相机轨迹。</p><p><strong>问题三：能干什么？</strong> 展示了 Vision Pro / Quest 上的 VR 浏览、导出 mesh 后接物理引擎做刚体与流体、导入 Unity/UE 做游戏、以及对单个物体做平移旋转缩放。</p><p>一个必须指出的缺口：整篇报告<strong>没有 ablation</strong>。elevation-aware augmentation、circular denoising、跨层深度对齐、scene-aware negative prompt 这四个设计各贡献多少，没有任何量化证据。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：3D 场景数据太少，所以先把生成压回 2D，用全景当 360° 世界代理；全景只能转头不能走动，所以按语义把它拆成天空/背景/物体层，把遮挡区域 inpaint 补回来；每层配一张对齐过的深度图后用 sheet warping 变成网格，遮挡顺序自然保留，物体天然分离；走出全景覆盖范围时交给带世界缓存的 Voyager 做自回归扩展；结果是一个能压缩到十分之一体积、能进引擎、物体能拖动的分层 mesh 世界。</p><p><strong>三句话版</strong>：全景当世界代理解决了 3D 数据稀缺，VLM 分层解决了遮挡与可交互性，sheet warping 解决了与图形管线的兼容性。在四组对比（图/文 × 全景/世界）上全项优于 Diffusion360、MVDiffusion、PanFusion、LayerPano3D、WonderJourney、DimensionX、Director3D。代价是整份报告没有 ablation，各组件贡献不可分辨。</p><p><strong>一句话版</strong>：把&quot;生成 3D 世界&quot;改写成&quot;生成一张全景、按语义分层、逐层 warp 成网格&quot;，从而同时拿到 360° 沉浸、mesh 导出与物体解耦。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>一张全景加上估计出来的分层深度，足以支撑视点的自由平移</strong>。这个假设一旦不成立，&quot;explorable&quot;这半个卖点就失效——因为被遮挡区域的内容是 inpaint 猜出来的，不是观测来的；层间深度只靠重叠区域做最小化对齐，没有多视角约束校正尺度。</p><p>实践中它很容易不成立：室内近距离场景 parallax 极强，走两步就会暴露 sheet warping 的拉伸三角面与空洞；树叶、栏杆、玻璃这类深度估计本身不可靠的结构，分层再多也补不出正确几何。</p><p>论文提供的证据其实回避了这一点：所有定量评测的渲染轨迹都是<strong>纯方位角旋转</strong>（0°–90° 或 0°–300°），几乎没有平移；真要走远时，系统把任务交给 Voyager 这个独立的视频模型接管。缺失的证据是：分层 mesh 单独能支持多大范围的平移而不崩，论文没有给任何量化刻画。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，且不需要训练任何模型：</p><ul><li><strong>数据</strong>：10 张公开全景（室内 5 张、室外 5 张），用 MoGe 估深度。</li><li><strong>实现</strong>：写一个 sheet warping 脚本（深度反投影 + 像素邻接连面 + 极区平滑），做两个版本——单层，以及手工两层（用 SAM 抠出主要前景，用任意 inpainting 模型补背景后单独 warp）。</li><li><strong>测量</strong>：相机沿一条直线从全景中心平移 0.5 / 1 / 2 / 4 米，渲染 90° FOV 视图，测量空洞像素占比与 BRISQUE。</li><li><strong>判据</strong>：若两层版在 2 米处的空洞占比显著低于单层版，支持&quot;分层是可探索性的来源&quot;这一 claim；若两者在同一距离一起崩，说明本文的定量优势主要来自 Panorama-DiT 的全景质量，而非分层表示。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是提供<strong>替代解释</strong>：所有指标（BRISQUE、NIQE、Q-Align、CLIP-I/T）都是在渲染出的 2D 透视图上算的图像级指标，对 3D 几何是否正确基本不敏感。只要 Panorama-DiT 生成的全景比基线漂亮，全部四张表的领先就都能被解释掉，与分层 mesh 无关。</p><p>设计一个交叉实验拆开这两个因素：把 HunyuanWorld 生成的全景喂给 LayerPano3D 的重建管线，把 LayerPano3D 生成的全景喂给本文的分层 mesh 管线，四种组合各渲同一套视角。如果指标主要跟着&quot;全景来源&quot;走而不是跟着&quot;重建管线&quot;走，那么分层网格表示的贡献被系统性高估了——注意文生世界那一组本文与 LayerPano3D 的差距（34.6 对 35.3）已经暗示了这种可能。</p><p>另一类可预测失败：给一张强反射的玻璃幕墙街景或一片密林作为输入，单目深度会给出错误的层次关系，NMS 合并跨边界碎片也会把不同建筑并成一个实例，此时&quot;物体解耦&quot;这个卖点会退化成随机切割。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>不要沿着&quot;更好的全景 + 更准的深度&quot;往下做，那是增量。换一个 framing：<strong>把世界生成的输出从&quot;分层几何&quot;升级为&quot;带物理与关节属性的可执行场景&quot;</strong>。</p><p>驱动它的局限很明确——本文的层只是 RGB mask 加深度，物体拖得动但没有质量、摩擦、铰链，导出的 mesh 进物理引擎后仍然是一堆没有语义的碰撞体，对具身智能没有直接价值。可借鉴的相邻领域工具是 articulated object 生成与 PartNet-Mobility 类的关节先验，以及 VLM 在物体功能推理上的能力：让 VLM 在识别实例时同时输出&quot;这是可开合的柜门 / 这是固定的墙体 / 这个质量大约 2kg&quot;，再用关节资产生成模型把假设兑现成可动部件。</p><p>第一个实验很具体：取 20 个室内场景提示词，用增强后的管线生成带关节假设的场景，导入 Isaac Sim，让一个现成的抓取 policy 在其中执行&quot;打开抽屉取出物体&quot;，与在真实扫描场景（如 ScanNet 重建）中的成功率对比。如果差距能控制在可接受范围内，那么&quot;文本 → 可仿真世界&quot;这条链路才算真正打通，而不只是&quot;文本 → 好看的静态几何&quot;。</p>',46)])])}const m=s(r,[["render",o]]);export{h as __pageData,m as default};
